/* banco: escutas e leituras viram tarefas para lançar */
function provasBank(T0){
  const out=[];
  for (const lang of ['EN','FR']) for (const level of ['A1','A2','B1','B2','C1']){
    (ESCUTAS[lang][level]||[]).forEach(([title,audio,list],k)=>out.push({id:uid(),lang,level,topic:'Escuta',title:(lang==='FR'?'Écoute · ':'Listening · ')+title,instructions: lang==='FR'? 'Écoutez et répondez. Vous pouvez écouter plusieurs fois.' : 'Listen and answer. You can listen more than once.',audio,questions:fromRaw(list),uses:hashStr(title)%6,mine:false,createdAt:T0-20*DAY+k*MIN}));
    (LEITURAS[lang][level]||[]).forEach(([title,text,list],k)=>out.push({id:uid(),lang,level,topic:'Leitura',title:(lang==='FR'?'Lecture · ':'Reading · ')+title,instructions:(lang==='FR'? 'Lisez le texte et répondez.' : 'Read the text and answer.')+'\n\n'+text,questions:fromRaw(list),uses:hashStr(title)%6,mine:false,createdAt:T0-20*DAY+k*MIN}));
  }
  return out;
}
